importScripts("./basis_transcoder.js");let basis=null,formats=null;const pending=[];BASIS().then(e=>{e.initializeBasis(),basis=e;for(const s of pending)s();pending.length=0});function transcode({id:e,buffer:s}){const t=new basis.KTX2File(new Uint8Array(s));try{if(!t.isValid())throw new Error("invalid ktx2");const r=!!t.getHasAlpha(),o=r?formats.alpha:formats.opaque,c=t.getLevels();if(!t.startTranscoding())throw new Error("startTranscoding failed");const a=[],l=[];for(let n=0;n<c;n++){const f=t.getImageLevelInfo(n,0,0),g=t.getImageTranscodedSizeInBytes(n,0,0,o),i=new Uint8Array(g);if(!t.transcodeImage(i,n,0,0,o,0,-1,-1))throw new Error(`transcode failed at level ${n}`);a.push({width:f.origWidth,height:f.origHeight,data:i}),l.push(i.buffer)}self.postMessage({id:e,width:t.getWidth(),height:t.getHeight(),hasAlpha:r,levels:a},l)}catch(r){self.postMessage({id:e,error:String(r&&r.message||r)})}finally{t.close(),t.delete()}}self.onmessage=({data:e})=>{if(e.type==="init"){formats={opaque:e.opaque,alpha:e.alpha};const s=()=>self.postMessage({type:"ready"});basis?s():pending.push(s);return}if(e.type==="transcode"){if(!basis||!formats){self.postMessage({id:e.id,error:"not initialised"});return}transcode(e)}};
